class Arena { /* ... implementation as in text ... */ };

template <typename T>
struct ArenaAllocator {
    Arena* arena;
    ArenaAllocator(Arena& a) : arena(&a) {}
    // ... allocate/deallocate delegates to arena ...
};

std::vector<int, ArenaAllocator<int>> processData() {
    Arena localArena(1024 * 1024); // 1MB on stack
    std::vector<int, ArenaAllocator<int>> vec((ArenaAllocator<int>(localArena)));

    vec.reserve(100);
    vec.push_back(42);

    return vec; // Return by value (Move semantics)
}
